// Send via the same MediaController you already hold
fun playSfx(
    controller: MediaController,
    url: String,
    vol: Float,
    source: String = "unknown",
) {
    if (url.isBlank()) {
        Timber.tag(VOICE_SFX_LOG_TAG).w("playSfx[$source]: skip — blank url")
        return
    }
    Timber.tag(VOICE_SFX_LOG_TAG).d(
        "playSfx[$source]: send PLAY_SFX url=%s volume=%.2f mainPlaying=%s mainPlayWhenReady=%s playbackState=%d",
        url,
        vol,
        controller.isPlaying,
        controller.playWhenReady,
        controller.playbackState,
    )
    val args = Bundle().apply {
        putString("url", url)
        putFloat("volume", vol)
    }
    val future = controller.sendCustomCommand(AudioPlaybackService.Commands.PLAY_SFX, args)
    future.addListener(
        {
            try {
                val result = future.get()
                Timber.tag(VOICE_SFX_LOG_TAG).d(
                    "playSfx[$source]: command result=%d (%s)",
                    result.resultCode,
                    if (result.resultCode == androidx.media3.session.SessionResult.RESULT_SUCCESS) {
                        "SUCCESS"
                    } else {
                        "FAILED"
                    },
                )
            } catch (e: Exception) {
                Timber.tag(VOICE_SFX_LOG_TAG).e(e, "playSfx[$source]: command failed")
            }
        },
        MoreExecutors.directExecutor(),
    )
}

fun stopSfx(controller: MediaController, source: String = "unknown") {
    Timber.tag(VOICE_SFX_LOG_TAG).d("stopSfx[$source]")
    val future = controller.sendCustomCommand(AudioPlaybackService.Commands.STOP_SFX, Bundle.EMPTY)
    future.addListener(
        {
            try {
                val result = future.get()
                Timber.tag(VOICE_SFX_LOG_TAG).d("stopSfx[$source]: result=%d", result.resultCode)
            } catch (e: Exception) {
                Timber.tag(VOICE_SFX_LOG_TAG).e(e, "stopSfx[$source]: command failed")
            }
        },
        MoreExecutors.directExecutor(),
    )
}

