/**
 * Background voice music must use [C.USAGE_MEDIA] (same stream as the voice track).
 * [C.USAGE_ASSISTANCE_SONIFICATION] is often inaudible while media with audio focus plays.
 */
private fun ensureSfxPlayer(): ExoPlayer {
    sfxPlayer?.let { return it }
    val main = requireNotNull(player) { "Main player must be created before SFX player" }
    val attrs = AudioAttributes.Builder()
        .setContentType(C.AUDIO_CONTENT_TYPE_MUSIC)
        .setUsage(C.USAGE_MEDIA)
        .build()
    val p = ExoPlayer.Builder(this)
        .setAudioSessionId(main.audioSessionId)
        .setAudioAttributes(attrs, /* handleAudioFocus= */ false)
        .setHandleAudioBecomingNoisy(true)
        .build()
        .apply {
            repeatMode = Player.REPEAT_MODE_ONE
        }
    sfxPlayerListener = object : Player.Listener {
        override fun onPlaybackStateChanged(state: Int) {
            Timber.tag(VOICE_SFX_LOG_TAG).d(
                "sfx onPlaybackStateChanged: state=%d isPlaying=%s volume=%.2f",
                state,
                p.isPlaying,
                p.volume,
            )
        }

        override fun onPlayerError(error: androidx.media3.common.PlaybackException) {
            Timber.tag(VOICE_SFX_LOG_TAG).e(error, "sfx onPlayerError: %s", error.message)
        }
    }
    p.addListener(sfxPlayerListener!!)
    sfxPlayer = p
    Timber.tag(VOICE_SFX_LOG_TAG).d(
        "ensureSfxPlayer: sessionId=%d (main=%d)",
        p.audioSessionId,
        main.audioSessionId,
    )
    return p
}

private fun playVoiceBackgroundMusic(url: String, volume: Float) {
    val main = player
    val p = ensureSfxPlayer()
    Timber.tag(VOICE_SFX_LOG_TAG).d(
        "playVoiceBackgroundMusic: url=%s volume=%.2f mainPlaying=%s sfxSessionId=%d",
        url,
        volume,
        main?.isPlaying,
        p.audioSessionId,
    )
    p.volume = volume
    p.setMediaItem(MediaItem.fromUri(url))
    p.prepare()
    p.playWhenReady = true
}

