import io.noties.markwon.AbstractMarkwonPlugin
import io.noties.markwon.Markwon
import io.noties.markwon.core.MarkwonTheme

/**
 * Article markdown viewer based on Markwon (same stack as Twain [MarkdownText]).
 * Disables the horizontal rule under H1/H2 ([MarkwonTheme.headingBreakHeight]).
 */
@Composable
fun ArticleMarkdownText(
    markdown: String,
    modifier: Modifier = Modifier,
    color: Color = Color.Unspecified,
    @FontRes fontResource: Int? = null,
    style: TextStyle = LocalTextStyle.current,
) {
    val defaultColor = LocalContentColor.current.copy(alpha = LocalContentAlpha.current)
    val context = LocalContext.current
    val textColor = color.takeOrElse { style.color.takeOrElse { defaultColor } }
    val markwon = remember {
        Markwon.builder(context)
            .usePlugin(
                object : AbstractMarkwonPlugin() {
                    override fun configureTheme(builder: MarkwonTheme.Builder) {
                        builder.headingBreakHeight(0)
                    }
                }
            )
            .build()
    }

    AndroidView(
        modifier = modifier,
        factory = { ctx ->
            TextView(ctx).apply {
                setTextColor(textColor.toArgb())
                fontResource?.let { typeface = ResourcesCompat.getFont(ctx, it) }
            }
        },
        update = { textView ->
            markwon.setMarkdown(textView, markdown.replace("\r\n", "\n").trimIndent())
        },
    )
}

